$items=aps_gallery_items($con);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gallery Editor</title><style>body{margin:0;background:#f3f7fa;color:#183650;font:15px Arial}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.card{background:#fff;border:1px solid #d7e2ea;border-radius:14px;padding:24px;margin-top:18px}label{display:block;font-weight:bold;margin:12px 0 6px}input{width:100%;box-sizing:border-box;padding:10px;border:1px solid #c8d6e2;border-radius:7px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:15px}.item{border:1px solid #dce5eb;border-radius:8px;overflow:hidden}.item img{display:block;width:100%;height:150px;object-fit:cover}.item div{padding:10px}.item p{margin:0 0 9px;font-weight:bold}button,a{display:inline-block;padding:10px 13px;border:0;border-radius:7px;background:#08766f;color:#fff;text-decoration:none;font-weight:bold;cursor:pointer}.remove{background:#a12f37}.msg{padding:12px;border-radius:8px}.ok{background:#e6f7ef;color:#126443}.bad{background:#fff0f0;color:#9f2933}</style></head><body><main class="wrap"><a href="website-editor.php">← Website editor</a><section class="card"><h1>Photo gallery</h1><?php if($message){?><p class="msg <?php echo $tone;?>"><?php echo aps_website_escape($message);?></p><?php }?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?php echo aps_website_escape($_SESSION['aps_gallery_csrf']);?>"><label>Caption<input name="caption" maxlength="180" required></label><label>Photo<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><p>JPG, PNG, or WebP; maximum 5 MB.</p><button name="upload">Upload and publish</button></form></section><section class="card"><h2>Published photos</h2><div class="grid"><?php foreach($items as $item){?><article class="item"><img src="<?php echo aps_website_escape($item['image_path']);?>" alt="<?php echo a